+    public void testDynamicMatch() throws IOException {
+        List<Map<String, Object>> values = List.of(
+            Map.of("aaa", 124, "bbb", false, "ccc", 12.34),
+            Map.of("aaa", 124, "bbb", false, "ccc", 12.34)
+        );
+
+        var sut = new SourceMatcher(
